export interface ContextResponse {
  capabilities?: string[];
  project: string;
  /** Стабильный идентификатор пути конфигурации проекта */
  projectId: string;
  configPath: string;
  storagePath: string;
  /** Автор изменений, заданный при запуске сервера */
  actor: string;
  config: {
    version: 1;
    /** @default "local" */
    mode: "local";
    projectId?: string;
    projectSettings?: {
      /**
       * Отображаемое имя проекта, от 1 до 120 символов без переносов строк
       * @minLength 1
       * @maxLength 120
       * @pattern ^[^\p{Cc}]+$
       */
      name: string;
      /**
       * Slug адреса: 2–64 строчные латинские буквы/цифры с одиночными дефисами между частями
       * @minLength 2
       * @maxLength 64
       * @pattern ^[a-z0-9]+(?:-[a-z0-9]+)*$
       */
      slug: string;
      /**
       * Ревизия настроек проекта для защиты от одновременного редактирования
       * @min 0
       * @max 9007199254740991
       */
      revision: number;
      version: 1;
    };
    /** @minLength 1 */
    storageDir: string;
    /** @minLength 1 */
    defaultStatus: string;
    /** @minItems 1 */
    readyStatuses: string[];
    statuses: Partial<
      Record<
        string,
        {
          /** @default false */
          terminal: boolean;
          /** @default false */
          satisfiesDependencies: boolean;
          color?: ContextResponseColorEnum;
        }
      >
    >;
    mcp?: {
      /**
       * @min 0
       * @max 65535
       * @default 4710
       */
      port: number;
    };
    /** @default {"port":4700} */
    server: {
      /**
       * @min 0
       * @max 65535
       * @default 4700
       */
      port: number;
      /** @format uri */
      url?: string;
    };
    /** @default {"format":"text","defaultLimit":20,"maxBytes":16384} */
    output: {
      /** @default "text" */
      format: ContextResponseFormatEnum;
      /**
       * @min 1
       * @max 100
       * @default 20
       */
      defaultLimit: number;
      /**
       * @min 1024
       * @max 16777216
       * @default 16384
       */
      maxBytes: number;
    };
  };
}

